 ('SYN-TT-1482', 'post', 'reclutamiento_directo', 'Andamos reclutando raza. puro jale serio. pagos semanales y vacaciones. manden mensaje al privado y únete a la fila. es por tu familia. 🔥', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2026-08-08 15:53:00', '#chamba #jale', NULL, 'convoy de camionetas en terracería', NULL, TRUE, TRUE, FALSE, FALSE, TRUE),
 ('SYN-TT-1483', 'post', 'cultura_sin_reclutamiento', 'Esta rola pega bien duro 🔥🔥', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2026-09-06 11:22:00', '#fyp #corridos #regional', 'corrido bélico (sin título visible)', 'concierto', NULL, FALSE, FALSE, FALSE, TRUE, TRUE),
 ('SYN-TT-1484', 'post', 'reclutamiento_directo', 'Todavía hay plazas!!! puro jale serio manda DM es por tu familia 🐓😎🥚🥚', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2026-07-12 12:09:00', '#parati #jale #chamba', 'Operativa bélica', 'hombre con chaleco táctico y casco de espaldas en una camioneta', NULL, TRUE, TRUE, FALSE, TRUE, TRUE),
 ('SYN-TT-1485', 'post', 'cultura_sin_reclutamiento', 'Viernes de corridos con la raza', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2025-04-16 18:14:00', '#corridos #parati', 'corrido bélico (sin título visible)', 'concierto', NULL, FALSE, FALSE, FALSE, TRUE, TRUE),
 ('SYN-TT-1486', 'post', 'aspiracion_belica', 'Mi compa me pide que le consiga jale donde trabajo. Yo en corto: 😎🥷👹 🐓🆖', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2026-04-21 02:51:00', NULL, 'Ratón y queso - Alberto Ramón', 'tablero de auto de noche', NULL, FALSE, TRUE, TRUE, TRUE, TRUE),
 ('SYN-TT-1487', 'post', 'aspiracion_belica', 'Al único círculo social que me interesa pertenecer (en proceso) 💀🇲🇽', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2025-11-29 15:18:00', '#regional #belico', 'Seguimos laborando - Grupo 360', 'avioneta en construcción improvisada', NULL, FALSE, TRUE, TRUE, TRUE, TRUE),
 ('SYN-TT-1488', 'post', 'legitima_control', '¿Buscas trabajo? Vacante de mesero(a) fines de semana en Tijuana, $1,800 semanal más propinas. Presentarse con solicitud elaborada', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2026-06-17 00:27:00', '#trabajo', NULL, NULL, 1800, FALSE, FALSE, FALSE, FALSE, TRUE),
 ('SYN-TT-1489', 'post', 'reclutamiento_directo', '¿Quieres jale?. todo México 🇲🇽. pagos semanales y vacaciones. comenta info y te escribimos. el que no se arriesga no gana 😎. 🥚🥚🫡 plaza Uruapan', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2025-08-06 21:07:00', NULL, 'El Doble R', NULL, NULL, TRUE, FALSE, FALSE, TRUE, TRUE),
 ('SYN-TT-1490', 'post', 'reclutamiento_directo', '¿Buscas chamba? todo México 🇲🇽 para más info mandar mensaje esta es tu oportunidad para salir adelante 🫡 😈🥷', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2026-05-13 18:17:00', '#fyp', 'audio de radio de comunicación', NULL, NULL, TRUE, FALSE, FALSE, TRUE, TRUE),
 ('SYN-TT-1491', 'post', 'reclutamiento_directo', 'Hay jale para los que no se rajan, estamos buscando personal, pago semanal de $10,000, manda DM, esta es tu oportunidad para salir adelante 🫡, 🥷 zona Irapuato', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2026-04-01 16:34:00', NULL, 'El Doble R', NULL, 10000, TRUE, FALSE, FALSE, TRUE, TRUE),
 ('SYN-TT-1492', 'post', 'reclutamiento_directo', 'Todavía hay plazas!!!, trabajo para hombres y mujeres 🙋‍♀️🙋‍♂️, pagos semanales y vacaciones, comenta info y te escribimos, 🥚🥚👹', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2025-10-05 18:22:00', NULL, 'El Doble R', NULL, NULL, TRUE, FALSE, FALSE, TRUE, TRUE),
 ('SYN-TT-1493', 'comment', 'autopostulacion', 'alguien anda reclutando? soy de Zapopan', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2026-10-11 16:31:00', NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, TRUE),
