 ('SYN-TT-1496', 'post', 'reclutamiento_directo', 'Seguimos con el reclutamiento activo. no se ocupa experiencia. pagos semanales y vacaciones. manda DM. aquí sí hay futuro. 💀🆖', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2026-10-29 21:24:00', '#jale #chamba', NULL, 'grupo encapuchado junto a camionetas', NULL, TRUE, TRUE, FALSE, FALSE, TRUE),
 ('SYN-TT-1497', 'post', 'reclutamiento_directo', '¿Quieres jale? gente de 🥚🥚 conscientes del trabajo pagamos 10mil a 13mil pesos semanales 💵 escribe al privado o comenta para inf esta es tu oportunidad para salir adelante 🫡 💀🫡 jale en Tijuana', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2025-03-25 18:48:00', '#trabajo #jale', 'audio de radio de comunicación', NULL, 10000, TRUE, FALSE, FALSE, TRUE, TRUE),
 ('SYN-TT-1498', 'post', 'reclutamiento_directo', '¿Buscas chamba?. trabajo para hombres y mujeres 🙋‍♀️🙋‍♂️. manden mensaje al privado y únete a la fila. el que no se arriesga no gana 😎. 🥷 zona Apatzingán', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2025-04-03 03:19:00', NULL, 'corrido bélico (sin título visible)', NULL, NULL, TRUE, FALSE, FALSE, TRUE, TRUE),
 ('SYN-TT-1499', 'post', 'reclutamiento_directo', 'Andamos reclutando raza, no se ocupa experiencia, manda DM, 🆖', (SELECT platform_id FROM platforms WHERE platform_type = 'tiktok' LIMIT 1), '2025-10-24 13:07:00', '#trabajo #parati #reclutamiento', 'trap bélico', NULL, NULL, TRUE, FALSE, FALSE, TRUE, TRUE),
